@pytest.mark.parametrize("case", indirect=False, argvalues=[], ids=[])
def test_realtime_api_table_driven(
    api_client,
    endpoint: str,
    test_data: List[Dict[str, Any]],
    validator: SwaggerSchemaValidator,
    request_schema_required_q: Dict[str, Any],
    request_schema_optional_q: Dict[str, Any],
    response_schema_200: Dict[str, Any],
    response_schema_error: Dict[str, Any],
    allowed_status_codes: List[int],
):
    """
    Table-driven test for GET /v1/current.json covering all table items.
    - Validates request params (strict for intended 200, loose for others).
    - Sends the request using APIClient from conftest.
    - Asserts status codes are within spec-defined set.
    - Validates response bodies using validator against proper schema.
    - Skips unsupported status codes (e.g., 201).
    """
    # Iterate all objects in current_json.json as required
    for idx, case in enumerate(test_data):
        expected_status = case.get("statusCode")
        scenario = case.get("scenario", f"case-{idx}")

        # Skip cases not defined in the spec (e.g., 201)
        if not isinstance(expected_status, int) or not _is_status_supported_by_spec(expected_status, allowed_status_codes):
            pytest.skip(f"Scenario '{scenario}' expects unsupported status {expected_status} per spec; skipping.")

        params = _extract_params_from_case(case)

        # Validate request before sending using appropriate schema
        # For intended 200 status, require 'q'; otherwise, allow missing 'q'
        if expected_status == 200:
            # If params are missing 'q', we cannot form a valid success-request without hardcoding; skip.
            try:
                validator.validate_with_schema(params, request_schema_required_q)
            except Exception:
                pytest.skip(f"Scenario '{scenario}': missing 'q' in table-driven data; skipping success-path request validation.")
        else:
            validator.validate_with_schema(params, request_schema_optional_q)

        # Perform request
        resp = api_client.get(endpoint=endpoint, params=params)
        actual_status = resp.status_code

        # Assert status code is one of the spec-defined outcomes
        assert actual_status in allowed_status_codes, (
            f"[{scenario}] Unexpected status code: {actual_status}. "
            f"Must be one of {allowed_status_codes}"
        )

        # Parse JSON safely, default to {} for validation if empty/invalid JSON
        try:
            body = resp.json()
        except ValueError:
            body = {}

        # Response validation by actual status
        if actual_status == 200:
            validator.validate_with_schema(body, response_schema_200)
        elif actual_status in (400, 401, 403):
            validator.validate_with_schema(body, response_schema_error)
        else:
            pytest.fail(f"[{scenario}] Unhandled status code: {actual_status}")


